  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C19", "C20", "C21", "C35"],
  "claims": [
    {
      "claim": "The query is a small p-aminophenyl sulfonamide (sulfanilamide-type) with an acidic sulfonamide and a primary aromatic amine; the closest supplied empirical contexts are PABA and PAS, which share the para-aminophenyl acidic motif.",
      "card_ids": ["C10", "C19"]
    },
    {
      "claim": "PABA had F = 90.1 ± 8.7% in CF patients and was described as highly bioavailable with absorption similar to controls; PAS had F = 50–60% in humans.",
      "card_ids": ["C10", "C19", "C21"]
    },
    {
      "claim": "Additional PAS records show high absolute/relative bioavailability (118 ± 41% for sodium PAS capsules; 100% assumed for sodium PAS solution), reinforcing that the para-aminophenyl acid class is well absorbed orally despite ionization.",
      "card_ids": ["C20", "C35"]
    },
    {
      "claim": "No supplied record provides affirmative evidence that the query would have F < 20%; the query's ionization at pH 7.4 is not a low-F signal because the analogous PABA/PAS acids are also ionized yet highly bioavailable.",
      "card_ids": ["C10", "C19", "C20", "C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C20", "C21", "C35"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C22", "C23", "C24", "C25", "C26", "C27", "C28", "C29", "C30", "C31", "C32", "C33", "C34", "C36", "C37"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No matched oral versus intravenous AUC data are available for the query.",
    "Transfer from PABA/PAS is by structural analogy; the sulfonamide/isoxazole substituent may alter absorption, transport, or first-pass metabolism.",
    "No data address efflux, solubility-limited absorption, formulation, or food effects for the query.",
    "No data directly assess first-pass metabolism of the primary aromatic amine or the isoxazole ring."
  ],
  "decision_summary": "High: the closest transferable empirical contexts (PABA, PAS) show high oral bioavailability (90% and 50–60%, with additional PAS records at ~100–118%), the query is a small sulfanilamide-type analog, and no affirmative evidence supports F < 20%; confidence remains moderate because no direct query measurement exists."
}

